def PyTuple_Size(space, ref):
    """Take a pointer to a tuple object, and return the size of that tuple."""
    if not PyTuple_Check(ref):
        raise TypeError("Expected a tuple object")
    ref_tup = rffi.cast(PyTupleObject, ref)
    return ref_tup.c_size

def _obfuscate_command(self,
                       command_args: Sequence[CommandArg],
                       obfuscate_args: Optional[Iterable[CommandArg]] = None,
                       regex: Optional[str] = None) -> ObfuscatedCommand:
    obfuscate_args = set(chain((obfuscate_args or []), self.default_obfuscation))
    obfuscated = ' '.join(
        self.obfuscation if (arg in obfuscate_args or (regex and re.match(regex, str(arg)))) else shlex.quote(str(arg))
        for arg in command_args)
    return ObfuscatedCommand(obfuscated)

